/* Loads the contained interface, refinements, then the original offline JSZip build. */
(() => {
  const rebuiltUi = document.createElement("script");
  rebuiltUi.src = "./ui-rebuild.js?v=2026-08-05-r7";
  rebuiltUi.defer = true;
  rebuiltUi.addEventListener("load", () => {
    const tabletRefinements = document.createElement("link");
    tabletRefinements.rel = "stylesheet";
    tabletRefinements.href = "./theme-oriental-r5.css?v=2026-08-05-r7";
    tabletRefinements.dataset.tabletRefinements = "true";
    document.head.appendChild(tabletRefinements);

    const focusedRefinements = document.createElement("link");
    focusedRefinements.rel = "stylesheet";
    focusedRefinements.href = "./theme-oriental-r6.css?v=2026-08-05-r7";
    focusedRefinements.dataset.focusedRefinements = "true";
    document.head.appendChild(focusedRefinements);

    const landscapeRefinements = document.createElement("link");
    landscapeRefinements.rel = "stylesheet";
    landscapeRefinements.href = "./theme-oriental-r7.css?v=2026-08-05-r7";
    landscapeRefinements.dataset.landscapeRefinements = "true";
    document.head.appendChild(landscapeRefinements);

    const refinementScript = document.createElement("script");
    refinementScript.src = "./ui-refinements-r6.js?v=2026-08-05-r7";
    refinementScript.defer = true;
    document.head.appendChild(refinementScript);
  });
  document.head.appendChild(rebuiltUi);

  document.write('<script src="vendor/jszip-core.min.js"><\/script>');
})();
